package com.wangc.bill.reference.ui;

import android.app.AlertDialog;
import android.app.DatePickerDialog;
import android.content.Intent;
import android.view.View;
import android.widget.*;
import androidx.recyclerview.widget.RecyclerView;
import com.wangc.bill.reference.*;
import com.wangc.bill.reference.capture.PlanScheduler;
import org.json.JSONObject;
import java.util.*;

final class FinancialScreens {
    private FinancialScreens(){}
    static void render(ManagerActivity a){switch(a.page){case "goals"->goals(a);case "edit_goal"->goal(a);case "plans"->plans(a);case "edit_plan"->plan(a);case "lending","reimbursement","loans"->returns(a);case "investments"->investments(a);}}
    static void goals(ManagerActivity a){View r=a.original("存钱目标","activity_dream_list");Runnable add=()->a.open("edit_goal",0);Ui.click(r,"btn_add",add);Ui.click(r,"add_dream",add);Ui.hide(r,"btn_more");List<JSONObject> goals=a.store().query("SELECT * FROM goals ORDER BY id DESC");Ui.show(r,"tip_layout",goals.isEmpty());RecyclerView list=Ui.view(r,"dream_list");
        // Recovered containers and colors, with a small local progress card.
        list.setLayoutManager(new androidx.recyclerview.widget.LinearLayoutManager(a));list.setAdapter(new RecyclerView.Adapter<RecordAdapter.Holder>(){public int getItemCount(){return goals.size();}public RecordAdapter.Holder onCreateViewHolder(android.view.ViewGroup parent,int type){return new RecordAdapter.Holder(Ui.row(a,"","",null));}public void onBindViewHolder(RecordAdapter.Holder holder,int position){JSONObject g=goals.get(position);LinearLayout row=(LinearLayout)holder.itemView;((TextView)row.getChildAt(0)).setText(g.optString("name"));long target=g.optLong("target"),saved=g.optLong("saved");((TextView)row.getChildAt(1)).setText("已存 ¥"+Money.text(saved,"CNY")+" / ¥"+Money.text(target,"CNY")+" · "+Math.min(100,Math.round(saved*100.0/target))+"%");row.setOnClickListener(v->a.open("edit_goal",g.optLong("id")));}});
    }
    static void goal(ManagerActivity a){JSONObject old=a.entity>0?a.store().one("SELECT * FROM goals WHERE id=?",""+a.entity):null;View r=a.original(a.entity==0?"新增目标":"编辑目标","activity_add_dream");EditText name=Ui.view(r,"dream_name"),target=Ui.view(r,"dream_total_num"),saved=Ui.view(r,"dream_start_num");name.setText(old==null?"":old.optString("name"));target.setText(Money.text(old==null?0:old.optLong("target"),"CNY"));saved.setText(Money.text(old==null?0:old.optLong("saved"),"CNY"));Ui.text(r,"dream_start_num_title","已存金额（CNY）");Ui.text(r,"dream_total_num_title","目标金额（CNY）");Ui.hide(r,"dream_remark","dream_remark_title","dream_start_time_layout","dream_end_time_layout","dream_type_layout","add_cycle_layout","add_num_layout","income_category_layout","pay_category_layout","asset_layout","ratio_layout");Ui.show(r,"btn_delete",a.entity>0);Ui.click(r,"btn_delete",()->Ui.confirm(a,"删除目标","账单不会受影响。",()->{a.store().deleteSimple("goals",a.entity);a.finish();}));Ui.click(r,"btn_complete",()->{try{a.store().saveGoal(a.entity,name.getText().toString(),Money.positive(target.getText().toString(),"CNY"),Money.signed(saved.getText().toString(),"CNY"));a.finish();}catch(Exception e){Ui.error(a,e);}});}
    static void plans(ManagerActivity a){a.body("周期记账","新增",()->a.open("edit_plan",0));a.rows.addView(Ui.row(a,"检查到期账单","到期后生成待确认记录；Android 省电限制可能使后台检查延迟。",()->{PlanScheduler.sync();Ui.page(a,"inbox");}));for(JSONObject p:a.store().query("SELECT * FROM plans ORDER BY next_due")){JSONObject data=Json.parse(p.optString("payload")),book=a.store().book(data.optLong("book_id"));String currency=book==null?"CNY":book.optString("currency");LinearLayout row=Ui.row(a,p.optString("name"),Money.text(data.optLong("amount"),currency)+" · "+p.optString("interval")+" · "+Ui.date(p.optLong("next_due"),"yyyy-MM-dd")+(p.optInt("enabled")==1?" · 已启用":" · 已暂停"),()->a.open("edit_plan",p.optLong("id")));row.setOnLongClickListener(v->{a.store().enablePlan(p.optLong("id"),p.optInt("enabled")!=1);PlanScheduler.sync();a.reload();return true;});a.rows.addView(row);}}
    static void plan(ManagerActivity a){JSONObject old=a.entity>0?a.store().one("SELECT * FROM plans WHERE id=?",""+a.entity):null;JSONObject data=old==null?Json.object("book_id",a.bookId(),"kind","expense","category_id",a.store().defaultCategory("expense"),"account_id",0,"not_total",false,"not_budget",false):Json.parse(old.optString("payload"));String[] interval={old==null?"monthly":old.optString("interval")};long[] due={old==null?System.currentTimeMillis():old.optLong("next_due")};View r=a.original(old==null?"新增周期账单":"编辑周期账单","activity_cycle_set_simple");EditText amount=Ui.view(r,"num"),remark=Ui.view(r,"remark");JSONObject book=a.store().book(data.optLong("book_id"));String[] currency={book==null?a.currency():book.optString("currency")};amount.setText(Money.text(data.optLong("amount"),currency[0]));remark.setText(old==null?"":old.optString("name"));Ui.hide(r,"cycle_end_layout","cycle_add_time_layout","tag_layout","file_layout","reimbursement_layout");
        Runnable refresh=()->{JSONObject b=a.store().book(data.optLong("book_id"));Ui.text(r,"account_book",b==null?"请选择账本":b.optString("name"));Ui.text(r,"cycle_data_text",intervalName(interval[0]));Ui.text(r,"cycle_start_time",Ui.date(due[0],"yyyy-MM-dd"));JSONObject c=a.store().one("SELECT * FROM categories WHERE id=?",""+data.optLong("category_id"));Ui.text(r,"category",c==null?"请选择分类":c.optString("name"));if(c!=null)Ui.image(r,"category_icon",c.optString("icon"));JSONObject ac=a.store().one("SELECT name FROM accounts WHERE id=?",""+data.optLong("account_id"));Ui.text(r,"asset",ac==null?"无账户":ac.optString("name"));};refresh.run();
        Ui.click(r,"cycle_data_layout",()->new AlertDialog.Builder(a).setTitle("重复周期").setItems(new String[]{"每天","每周","每月","每年"},(d,w)->{interval[0]=new String[]{"daily","weekly","monthly","yearly"}[w];refresh.run();}).show());
        Ui.click(r,"cycle_start_time_layout",()->{Calendar c=Calendar.getInstance();c.setTimeInMillis(due[0]);new DatePickerDialog(a,(v,y,m,day)->{Calendar next=Calendar.getInstance();next.set(y,m,day,9,0,0);next.set(Calendar.MILLISECOND,0);due[0]=next.getTimeInMillis();Json.put(data,"anchor_day",day);refresh.run();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});
        Ui.click(r,"category_layout",()->{List<JSONObject> cats=a.store().query("SELECT * FROM categories WHERE archived=0 ORDER BY kind,id");String[] names=new String[cats.size()];for(int i=0;i<names.length;i++)names[i]=(cats.get(i).optString("kind").equals("income")?"收入·":"支出·")+cats.get(i).optString("name");new AlertDialog.Builder(a).setTitle("分类").setItems(names,(d,w)->{Json.put(data,"category_id",cats.get(w).optLong("id"));Json.put(data,"kind",cats.get(w).optString("kind"));refresh.run();}).show();});
        Ui.click(r,"account_book_layout",()->{List<JSONObject> books=a.store().books();String[] labels=new String[books.size()];for(int i=0;i<labels.length;i++)labels[i]=books.get(i).optString("name")+" · "+books.get(i).optString("currency");new AlertDialog.Builder(a).setTitle("账本").setItems(labels,(d,w)->{JSONObject b=books.get(w);Json.put(data,"book_id",b.optLong("id"));if(!currency[0].equals(b.optString("currency"))){amount.setText("0");Json.put(data,"account_id",0);}currency[0]=b.optString("currency");refresh.run();}).show();});
        Ui.click(r,"asset_layout",()->chooseAccount(a,currency[0],id->{Json.put(data,"account_id",id);refresh.run();}));bind(r,"switch_not_into_total",data,"not_total");bind(r,"switch_not_into_budget",data,"not_budget");Ui.show(r,"btn_delete",a.entity>0);Ui.click(r,"btn_delete",()->Ui.confirm(a,"删除周期规则","已生成的待确认记录不会删除。",()->{a.store().deleteSimple("plans",a.entity);PlanScheduler.sync();a.finish();}));
        Ui.click(r,"btn_complete",()->{try{Json.put(data,"amount",Money.positive(amount.getText().toString(),currency[0]));Json.put(data,"remark",remark.getText().toString());if(!data.has("anchor_day")){Calendar c=Calendar.getInstance();c.setTimeInMillis(due[0]);Json.put(data,"anchor_day",c.get(Calendar.DAY_OF_MONTH));}a.store().savePlan(a.entity,remark.getText().toString(),interval[0],data,due[0]);PlanScheduler.sync();a.finish();}catch(Exception e){Ui.error(a,e);}});
    }
    static String intervalName(String i){return switch(i){case "daily"->"每天";case "weekly"->"每周";case "yearly"->"每年";default->"每月";};}
    static void bind(View r,String id,JSONObject data,String key){View v=Ui.view(r,id);if(v instanceof CompoundButton b){b.setChecked(data.optBoolean(key));b.setOnCheckedChangeListener((button,value)->Json.put(data,key,value));}}
    interface Account{void selected(long id);}
    static void chooseAccount(ManagerActivity a,String currency,Account callback){List<JSONObject> accounts=a.store().query("SELECT * FROM accounts WHERE archived=0 AND currency=?",currency);String[] names=new String[accounts.size()+1];names[0]="无账户";for(int i=0;i<accounts.size();i++)names[i+1]=accounts.get(i).optString("name");new AlertDialog.Builder(a).setTitle("账户").setItems(names,(d,w)->callback.selected(w==0?0:accounts.get(w-1).optLong("id"))).show();}
    static void returns(ManagerActivity a){boolean reimb=a.page.equals("reimbursement");a.body(reimb?"待报销":a.page.equals("loans")?"借入与还款":"借入借出","新增",()->{String[] names=reimb?new String[]{"新增报销支出"}:new String[]{"借出","借入"};new AlertDialog.Builder(a).setTitle("记一笔").setItems(names,(d,w)->a.startActivity(new Intent(a,EditorActivity.class).putExtra("financial",reimb?"reimbursement":w==0?"lend":"borrow"))).show();});String clause=reimb?"financial_type='reimbursement'":"financial_type IN ('lend','borrow')";for(JSONObject row:a.store().query("SELECT * FROM transactions WHERE book_id=? AND deleted=0 AND "+clause+" ORDER BY time DESC",""+a.bookId())){long left=a.store().outstanding(row.optLong("id"));String type=row.optString("financial_type");String name=(type.equals("borrow")?"借入":type.equals("lend")?"借出":"报销")+" · "+row.optString("remark");a.rows.addView(Ui.row(a,name,"剩余 "+Money.text(left,row.optString("currency"))+" / "+Money.text(row.optLong("amount"),row.optString("currency")),()->new AlertDialog.Builder(a).setTitle(name).setItems(left>0?new String[]{"记录部分或全部回款","编辑原账单"}:new String[]{"编辑原账单"},(d,w)->{if(left>0&&w==0)returnAmount(a,row,left);else Ui.edit(a,row.optLong("id"),null);}).show()));}}
    static void returnAmount(ManagerActivity a,JSONObject row,long left){String currency=row.optString("currency");Dialogs.input(a,"回款金额（最多 "+Money.text(left,currency)+"）",Money.text(left,currency),true,value->{long amount=Money.positive(value,currency);if(amount>left)throw new IllegalArgumentException("金额超过剩余待结算金额");chooseAccount(a,currency,id->{try{a.store().financialReturn(row.optLong("id"),amount,id,System.currentTimeMillis());a.reload();}catch(Exception e){Ui.error(a,e);}});});}
    static void investments(ManagerActivity a){a.body("投资账户","新增",()->a.open("new_account",0));a.rows.addView(Ui.row(a,"手动记录持仓净值","行情和证券接口未接入。可建立投资账户，通过转账记录投入与取出，通过收入或支出记录收益和亏损。",null));for(JSONObject row:a.store().query("SELECT * FROM accounts WHERE archived=0 AND type='investment'"))a.rows.addView(Ui.row(a,row.optString("name"),row.optString("currency")+" · "+Money.text(a.store().accountBalance(row.optLong("id")),row.optString("currency")),()->a.open("account_detail",row.optLong("id"))));}
}
